begin;

-- Specialties (in-house vs outsourced default is adjustable per work order) ---
on conflict (code) do update set
  name = excluded.name, label = excluded.label,
  is_outsourced_default = excluded.is_outsourced_default;

-- Drivers -----------------------------------------------------------------
on conflict (code) do update set
  name = excluded.name, phone = excluded.phone, status = excluded.status;
-- 32 drivers

-- Mechanics ---------------------------------------------------------------
on conflict (code) do update set
  name = excluded.name, phone = excluded.phone,
  employment_type = excluded.employment_type, can_lift = excluded.can_lift,
  status = excluded.status;
-- 5 mechanics (incl. new hires)

-- Mechanic -> specialty mapping (primary vs backup proficiency) -----------
select m.id, s.id, 'primary'::proficiency from mechanics m, specialties s where m.code = 'M-01' and s.name = 'mesin'
union all
select m.id, s.id, 'backup'::proficiency from mechanics m, specialties s where m.code = 'M-01' and s.name = 'kolong'
union all
select m.id, s.id, 'primary'::proficiency from mechanics m, specialties s where m.code = 'M-02' and s.name = 'mesin'
union all
select m.id, s.id, 'backup'::proficiency from mechanics m, specialties s where m.code = 'M-02' and s.name = 'kolong'
union all
select m.id, s.id, 'primary'::proficiency from mechanics m, specialties s where m.code = 'M-03' and s.name = 'kolong'
union all
select m.id, s.id, 'primary'::proficiency from mechanics m, specialties s where m.code = 'M-03' and s.name = 'gerang'
union all
select m.id, s.id, 'primary'::proficiency from mechanics m, specialties s where m.code = 'M-04' and s.name = 'las'
union all
select m.id, s.id, 'primary'::proficiency from mechanics m, specialties s where m.code = 'M-05' and s.name = 'kolong'
on conflict (mechanic_id, specialty_id) do update set
  proficiency = excluded.proficiency;

-- Vendors (needed in v1 for outsourced work orders) -----------------------
on conflict (name) do update set
  contact = excluded.contact, phone = excluded.phone, status = excluded.status;
-- 30 vendors

-- Trucks (keyed by plate) -------------------------------------------------
on conflict (plate) do update set
  model = excluded.model, fleet_division = excluded.fleet_division,
  status = excluded.status;
-- 84 trucks

commit;

